// Auto-fill stitching rate from Item
// ===========================
frappe.ui.form.on("Stitching Entry", {
    item: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (!row.item) return;

        // Fetch custom_fixed_rate from Item master
        frappe.db.get_value("Item", row.item, "custom_fixed_rate")
            .then(r => {
                if (r && r.message && r.message.custom_fixed_rate) {
                    frappe.model.set_value(cdt, cdn, "rate", r.message.custom_fixed_rate);
                } else {
                    frappe.model.set_value(cdt, cdn, "rate", 0);
                }
            });
    },
});

